# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BİLGİ FELSEFESİ (EPİSTEMOLOJİ) VE BİLGİ AKTLARI</text>\n  <rect x="22" y="45" width="190" height="165" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="117" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ÖZNE (SÜJE)</text>\n  <text x="117" y="96" text-anchor="middle" font-size="11" fill="#1e3a8a">Bilen, algılayan, düşünen</text>\n  <text x="117" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">ve yönelen bilinçli varlık</text>\n  <text x="117" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">(İnsan Zihni)</text>\n  <text x="117" y="168" text-anchor="middle" font-size="10.5" fill="#1e3a8a">Aktif kavrayıcı taraf</text>\n  <rect x="242" y="45" width="216" height="165" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">BİLGİ AKTLARI (BAĞ)</text>\n  <text x="255" y="94" font-size="11" fill="#713f12">1. Algılama Aktı (Duyular)</text>\n  <text x="255" y="116" font-size="11" fill="#713f12">2. Düşünme Aktı (Kavramlar)</text>\n  <text x="255" y="138" font-size="11" fill="#713f12">3. Anlama Aktı (Sezgi / Bağlam)</text>\n  <text x="255" y="160" font-size="11" fill="#713f12">4. Açıklama Aktı (Neden-Sonuç)</text>\n  <text x="350" y="190" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">ÜRÜN: BİLGİ (Önerme)</text>\n  <rect x="488" y="45" width="190" height="165" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="583" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">NESNE (OBJE)</text>\n  <text x="583" y="96" text-anchor="middle" font-size="11" fill="#14532d">Bilinen, yönelinen, algılanan</text>\n  <text x="583" y="116" text-anchor="middle" font-size="11" fill="#14532d">reel veya ideal varlık</text>\n  <text x="583" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">(Dış Dünya / Kavram)</text>\n  <text x="583" y="168" font-size="10.5" fill="#14532d">Bilgiye konu olan taraf</text>\n  <rect x="22" y="222" width="656" height="28" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="240" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bilgi; bilen özne (süje) ile bilinen nesne (obje) arasında bilgi aktları aracılığıyla kurulan ilişkiden doğan üründür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">EPİSTEMOLOJİNİN TEMEL KAVRAMLARI: GERÇEKLİK, DOĞRULUK VE TEMELLENDİRME</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">GERÇEKLİK (REALİTE)</text>\n  <text x="30" y="88" font-size="10.8" fill="#1e3a8a">• Varlığın bir özelliğidir (Ontolojik)</text>\n  <text x="30" y="112" font-size="10.8" fill="#1e3a8a">• İnsan zihninden bağımsız var olma</text>\n  <text x="30" y="136" font-size="10.8" fill="#1e3a8a">• Zaman ve mekânda somut bulunuş</text>\n  <text x="30" y="160" font-size="10.8" fill="#1e3a8a">• Örnek: Masanın, ağacın, demirin</text>\n  <text x="30" y="180" font-size="10.8" fill="#1e3a8a">  dış dünyada var olması</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">DOĞRULUK (HAKİKAT / VERİTE)</text>\n  <text x="255" y="88" font-size="10.8" fill="#14532d">• Bilginin / yargının özelliğidir</text>\n  <text x="255" y="112" font-size="10.8" fill="#14532d">• Düşüncenin nesnesiyle uyuşması</text>\n  <text x="255" y="136" font-size="10.8" fill="#14532d">• Önermenin gerçekliğe uygunluğu</text>\n  <text x="255" y="160" font-size="10.8" fill="#14532d">• Örnek: «Demir ısıtılınca genleşir»</text>\n  <text x="255" y="180" font-size="10.8" fill="#14532d">  yargısının doğru olması</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">TEMELLENDİRME</text>\n  <text x="480" y="88" font-size="10.8" fill="#581c87">• İddianın dayanaklarını gösterme</text>\n  <text x="480" y="112" font-size="10.8" fill="#581c87">• Akıl yürütme ve kanıt sunma</text>\n  <text x="480" y="136" font-size="10.8" fill="#581c87">• Sanıyı (doksa) bilgiden (episteme)</text>\n  <text x="480" y="156" font-size="10.8" fill="#581c87">  ayıran mantıksal gerekçelendirme</text>\n  <text x="480" y="180" font-size="10.8" fill="#581c87">• Tutarlılık ve geçerlilik denetimi</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Nesnenin kendisi «gerçek», o nesne hakkında zihnin kurduğu uygun önerme ise «doğru» olarak nitelendirilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BİRİNCİ PROBLEM: DOĞRU BİLGİNİN İMKÂNI (OLANAĞI) PROBLEMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">GENEL GEÇER BİLGİ İMKÂNSIZDIR (SEPTİSİZM)</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• Sofistler (Görelilik / Relativizm):</text>\n  <text x="35" y="108" font-size="11" fill="#7f1d1d">  - Protagoras: «İnsan her şeyin ölçüsüdür.»</text>\n  <text x="35" y="128" font-size="11" fill="#7f1d1d">  - Gorgias: «Bilinse de başkasına aktarılamaz.»</text>\n  <text x="35" y="150" font-size="11.2" fill="#7f1d1d">• Septikler (Kuşkuculuk — Pyrrhon ve Timon):</text>\n  <text x="35" y="170" font-size="11" fill="#7f1d1d">  - Duyular yanıltıcıdır; karşıt kanıtlar eşittir.</text>\n  <text x="35" y="190" font-size="11" fill="#7f1d1d">  - Epokhe (Yargıdan kaçınma) → Ataraksia (Ruh dinginliği)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">DOĞRU BİLGİ MÜMKÜNDÜR (DOGMATİZM)</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• İnsan zihni varlığı doğru ve kesin olarak bilebilir.</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• Rasyonalizm (Akılcılık): Sokrates, Platon, Aristoteles,</text>\n  <text x="370" y="130" font-size="11" fill="#064e3b">  Fârâbî, Descartes, Hegel</text>\n  <text x="370" y="150" font-size="11" fill="#064e3b">• Empirizm (Deneycilik): J. Locke, D. Hume</text>\n  <text x="370" y="170" font-size="11" fill="#064e3b">• Kritisizm (Eleştiricilik): I. Kant (Akıl + Deney)</text>\n  <text x="370" y="190" font-size="11" fill="#064e3b">• Entüisyonizm (Sezgicilik): Gazâlî, H. Bergson</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Pyrrhon\'un septisizminde şüphe amaçtır; Descartes\'ın metodik şüphesinde ise şüphe doğru bilgiye ulaşmak için araçtır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
